import contextlib,io,json,sys
from mypy import api
programs = {'forward_member': 'class A:
    def __init__(self) -> None:
        self.data = []
        self.other = B().other
        self.data.append(1)
class B(A):
    @property
    def data(self) -> list[int]:
        return []
    @data.setter
    def data(self, value: list[int]) -> None:
        pass
    def __init__(self) -> None:
        self.other = 1
', 'forward_inherited_member': 'class A:
    def __init__(self) -> None:
        self.data = []
        self.other = C().value
        self.data.append(1)
class B(A):
    @property
    def data(self) -> list[int]:
        return []
    @data.setter
    def data(self, value: list[int]) -> None:
        pass
class C:
    def __init__(self) -> None:
        self.value = 1
', 'wrong_property_type': 'class A:
    def __init__(self) -> None:
        self.data = []
        self.other = B().other
        self.data.append(1)
class B(A):
    @property
    def data(self) -> list[str]:
        return []
    @data.setter
    def data(self, value: list[str]) -> None:
        pass
    def __init__(self) -> None:
        self.other = 1
'}
expect = {'forward_member': (1, 'has-type'), 'forward_inherited_member': (0, 'Success'), 'wrong_property_type': (1, '[override]')}
cases=[]
for name,code in programs.items():
    so,se=io.StringIO(),io.StringIO()
    with contextlib.redirect_stdout(so),contextlib.redirect_stderr(se):
        out,err,status=api.run(['--config-file=/dev/null','--no-incremental','--cache-dir=/tmp/p009v2-mypy-cache','--show-traceback','-c',code])
    text=out+so.getvalue();errors=err+se.getvalue()
    exp_status,exp_text=expect[name]
    ok=status==exp_status and exp_text in text and 'INTERNAL ERROR' not in text+errors
    cases.append({'case':name,'exit':status,'stdout':text[-900:],'stderr':errors[-300:],'pass':ok})
print(json.dumps({'cases':cases},sort_keys=True))
sys.exit(0 if all(c['pass'] for c in cases) else 1)
